using NUnit.Framework;

[TestFixture]
public class FirstRepeatedWordTests
{
    [Test]
    public void Returns_First_Repeated_Word()
    {
        var result = FirstRepeatedWord("Go home and go sleep");
        Assert.That(result, Is.EqualTo("go"));
    }

    private string? FirstRepeatedWord(string sentence)
    {
        var seen = new HashSet<string>();

        foreach (var word in sentence.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            var normalized = word.ToLowerInvariant();

            if (!seen.Add(normalized))
                return normalized;
        }

        return null;
    }
}
